--
-- Table structure for table `robokee`
--

DROP TABLE IF EXISTS `robokee`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `robokee` (
  `ro` smallint(6) NOT NULL default '0',
  `billno` mediumint(9) NOT NULL default '0',
  `bilorgindid` int(11) NOT NULL default '0',
  `billtype` varchar(30) NOT NULL default '',
  `status` char(1) NOT NULL default '',
  `orgind_name` varchar(200) default '',
  `city` varchar(60) default '',
  `country` varchar(50) NOT NULL default '',
  `weight` mediumint(9) default '0',
  `phone` varchar(100) NOT NULL default '',
  `remarks` varchar(330) default NULL,
  `carrier` varchar(60) NOT NULL default '',
  `pkg_regno` varchar(300) NOT NULL default '',
  `pkg_regdate` varchar(60) NOT NULL default '',
  `postage_paid` decimal(7,2) default '0.00',
  `create_date` datetime NOT NULL default '0000-00-00 00:00:00',
  PRIMARY KEY  (`ro`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8;
/*!40101 SET character_set_client = @saved_cs_client */;

